// Reading notes remain private to this browser; progress backups exclude them.
function loadReadingNote(){const n=$('#reading-note');if(n){try{n.value=localStorage.getItem(`dailoan-note:${$('#lesson-body')?.dataset.lesson}`)||'';}catch{}}}
